def check_sequence(n, a, K):
    a_k = a
    for k in range(1, K + 1):
        if a_k % k != 0:
            return False, k
        a_k = a_k // k + k**(n-1)
    return True, K

print(check_sequence(5, 57, 10))

def check_sequence_n5(a, K):
    a_k = a
    for k in range(1, K + 1):
        if a_k % k != 0:
            return False, k, a_k
        a_k = a_k // k + k**4
    return True, K, a_k

print(check_sequence_n5(537, 10))

def compute_p_minus_1(n):
    coeffs = [0] * n
    coeffs[n-1] = 1
    # c_{m-1} = sum_{i=m}^{n-1} c_i * binom(i, m) * (-1)^(i-m)
    import math
    def binom(n, k):
        return math.comb(n, k)

    for m in range(n-1, 0, -1):
        val = 0
        for i in range(m, n):
            val += coeffs[i] * binom(i, m) * ((-1)**(i-m))
        coeffs[m-1] = val

    p_minus_1 = 0
    for i in range(n):
        p_minus_1 += coeffs[i] * ((-1)**i)
    return p_minus_1

for n in range(1, 21):
    print(f"n={n}: P(-1)={compute_p_minus_1(n)}")
